<script lang="ts">import {onMount} from 'svelte';import AppHeader from '$lib/components/common/AppHeader.svelte';import AccountForm from '$lib/components/accounts/AccountForm.svelte';import {accountsApi} from '$lib/api';import type {Account} from '$lib/types';import {Pencil,Trash2} from 'lucide-svelte';let accounts:Account[]=[];let loading=true;let error='';let show=false;let editing:Account|null=null;$: active=accounts.filter(a=>a.is_active).length;$: total=accounts.reduce((n,a)=>n+Number(a.current_balance),0);async function load(){try{accounts=await accountsApi.list()}catch(e){error=e instanceof Error?e.message:'Could not load accounts'}finally{loading=false}}async function remove(a:Account){if(confirm(`Delete ${a.name}?`))try{await accountsApi.remove(a.id);load()}catch(e){error=e instanceof Error?e.message:'Could not delete account'}}onMount(load)</script>
<svelte:head><title>Accounts · Trade Track</title></svelte:head><main class="shell"><AppHeader title="Accounts" subtitle="Keep every strategy in its own lane"/><section class="grid summary"><div class="card"><div class="muted">Active accounts</div><h2>{active}</h2></div><div class="card"><div class="muted">Combined balance</div><h2>${total.toFixed(2)}</h2></div></section><div class="bar"><h2>Your accounts</h2><button class="btn" onclick={()=>{editing=null;show=true}}>+ Add account</button></div>{#if error}<p class="error">{error}</p>{:else if loading}<div class="empty">Loading accounts…</div>{:else if !accounts.length}<div class="card empty"><h2>No accounts yet</h2><p>Create an account before adding trades.</p></div>{:else}<section class="grid accounts">{#each accounts as a}<article class="card"><div class="top"><div><h3>{a.name}</h3><p>{a.broker||'No broker'} · {a.account_type}</p></div><span class:inactive={!a.is_active}>{a.is_active?'Active':'Inactive'}</span></div><div class="values"><div><small>Initial</small><strong>{a.currency} {Number(a.initial_balance).toFixed(2)}</strong></div><div><small>Current</small><strong>{a.currency} {Number(a.current_balance).toFixed(2)}</strong></div><div><small>P&amp;L</small><strong class:profit={Number(a.account_pnl)>=0} class:loss={Number(a.account_pnl)<0}>{Number(a.account_pnl)>=0?'+':''}{Number(a.account_pnl).toFixed(2)}</strong></div></div><footer><span>{a.trade_count} trades</span><div><button onclick={()=>{editing=a;show=true}}><Pencil size={16}/></button><button onclick={()=>remove(a)}><Trash2 size={16}/></button></div></footer></article>{/each}</section>{/if}{#if show}<AccountForm account={editing} close={()=>show=false} saved={load}/>{/if}</main>
<style>.summary{grid-template-columns:1fr 1fr;margin-bottom:26px}.summary h2{margin:8px 0 0}.bar,.top,footer{display:flex;align-items:center;justify-content:space-between}.accounts{grid-template-columns:repeat(auto-fit,minmax(300px,1fr))}h3{margin:0}.top p{font-size:.75rem;color:#8290a7;margin:4px 0}.top>span{background:#123b31;color:#35d07f;padding:4px 8px;border-radius:7px;font-size:.68rem}.top .inactive{background:#272c36;color:#8290a7}.values{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:22px 0}.values div{display:grid;gap:5px}.values small,footer{color:#8290a7;font-size:.72rem}.values strong{font-size:.9rem}footer{border-top:1px solid #1c2b42;padding-top:12px}footer button{background:transparent;border:0;color:#8290a7;cursor:pointer;padding:5px}</style>

